// Public types of @kaminide/bridge-workspace-host. Hand-written mirror of the
// exports of src/headless.ts; pack-headless.mjs copies it into the package.
// Keep both files in step until declarations are generated by the build.
import type { IncomingMessage, ServerResponse } from 'node:http'

/** Engine version this build was produced from. */
export declare const version: string

export declare const SESSION_COOKIE: 'kamin_workspace'
export declare function readSessionCookie(header: string | undefined): string | undefined
export declare function resetCredentials(storage: string): void

export interface PreviewDescriptor {
  name: string
  entry: string
  exposedModule: string
  props: Record<string, unknown>
  type: 'global' | 'module'
  revision: number
}

export interface HeadlessAuth {
  login(candidate: unknown): Promise<string | null>
  loginLocal(): Promise<string | null>
  validate(cookie: string | undefined): Promise<boolean>
  logout(cookie: string | undefined): void
  cookieHeader(cookie: string, secure: boolean): string
}

export interface HeadlessWorkspaceOptions {
  root: string
  storage: string
  serverUrl: string
  origin: string
  bind?: string
  port?: number
  auth: HeadlessAuth
  serveApp?: (request: IncomingMessage, response: ServerResponse) => void | Promise<void>
  env?: NodeJS.ProcessEnv
  onWatchError?: () => void
}

export interface HeadlessWorkspace {
  readonly preview: {
    copy(): PreviewDescriptor | null
    unmount(): void
    /** Fires on every mount, remount and unmount. Returns an unsubscribe function. */
    onRemount(listener: () => void): () => void
  }
  close(): Promise<void>
}

export declare function startHeadlessWorkspace(options: HeadlessWorkspaceOptions): Promise<HeadlessWorkspace>
